<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { api, apiMessage } from '@/api/client';
import { useRouter } from 'vue-router';
import { useAuthStore } from '@/stores/auth';
import type { SessionInfo, User } from '@/types';
import EmailVerificationPanel from '@/components/EmailVerificationPanel.vue';
import LegacyRecyclingPanel from '@/components/LegacyRecyclingPanel.vue';
import EmailChangePanel from '@/components/EmailChangePanel.vue';

interface MigrationPreview { checksum:string; sourceVersion:string; ready:boolean; plans:number; tasks:number; mainlines:number; mainlineItems:number; reflections:number; timeEntries:number; preservedOnly:number; warnings:string[]; errors:string[] }
interface MigrationHistory { importId:string; sourceVersion:string; checksum:string; status:string; createdAt:string; completedAt:string|null; rolledBackAt:string|null }

const auth=useAuthStore(); const router=useRouter(); const sessions=ref<SessionInfo[]>([]);
const profile=reactive({displayName:''}); const password=reactive({currentPassword:'',newPassword:'',confirmPassword:''}); const accountBusy=ref(false);
const fileName=ref(''); const payload=ref<unknown>(null); const preview=ref<MigrationPreview|null>(null); const history=ref<MigrationHistory[]>([]); const busy=ref(false); const message=ref(''); const error=ref('');
async function loadSessions(){sessions.value=(await api.get<SessionInfo[]>('/auth/sessions')).data;}
async function revokeSession(item:SessionInfo){busy.value=true;try{await api.delete(`/auth/sessions/${item.id}`);if(item.current){await auth.logout();await router.push('/login');}else await loadSessions();}catch(reason){error.value=apiMessage(reason);}finally{busy.value=false;}}
async function logoutEverywhere(){if(!confirm('将退出包括当前设备在内的全部登录会话。确认继续吗？'))return;busy.value=true;try{await auth.logoutAll();await router.push('/login');}catch(reason){error.value=apiMessage(reason);}finally{busy.value=false;}}
async function loadProfile(){const {data}=await api.get<User>('/auth/me');profile.displayName=data.displayName;auth.updateProfile(data);}
async function saveProfile(){accountBusy.value=true;error.value='';try{const {data}=await api.patch<User>('/auth/me',{displayName:profile.displayName});auth.updateProfile(data);message.value='个人资料已保存。';}catch(reason){error.value=apiMessage(reason);}finally{accountBusy.value=false;}}
async function changePassword(){if(password.newPassword!==password.confirmPassword){error.value='两次输入的新密码不一致。';return;}accountBusy.value=true;error.value='';try{await api.post('/auth/password',{currentPassword:password.currentPassword,newPassword:password.newPassword});await auth.logout();await router.push('/login');}catch(reason){error.value=apiMessage(reason);}finally{accountBusy.value=false;}}
async function loadHistory(){history.value=(await api.get<MigrationHistory[]>('/migrations/legacy')).data;}
async function choose(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;fileName.value=file.name;preview.value=null;message.value='';try{payload.value=JSON.parse(await file.text());preview.value=(await api.post<MigrationPreview>('/migrations/legacy/preview',payload.value)).data;error.value=preview.value.errors.join('；');}catch(reason){payload.value=null;error.value=reason instanceof SyntaxError?'JSON 文件无法解析。':apiMessage(reason);}}
async function migrate(){if(!payload.value||!preview.value?.ready)return;busy.value=true;try{const{data}=await api.post('/migrations/legacy/import',payload.value);message.value=`迁移完成：${data.tasks} 个计划任务、${data.mainlineItems} 个路线步骤、${data.timeEntries} 条计时流水。`;error.value='';await loadHistory();}catch(reason){error.value=apiMessage(reason);}finally{busy.value=false;}}
async function rollback(item:MigrationHistory){if(!confirm('将删除这一批迁移创建的周期计划和目标路线，原始 JSON 快照仍会保留。确认继续吗？'))return;busy.value=true;try{await api.post(`/migrations/legacy/${item.importId}/rollback`);message.value='迁移已回滚，原始快照仍保存在服务器。';error.value='';await loadHistory();}catch(reason){error.value=apiMessage(reason);}finally{busy.value=false;}}
onMounted(()=>{Promise.all([loadHistory(),loadSessions(),loadProfile()]).catch(reason=>{error.value=apiMessage(reason);});});
</script>
<template><div class="page"><section class="page-head"><div><p class="eyebrow">SETTINGS / SECURITY / MIGRATION</p><h1>账号安全与数据迁移</h1></div><p>管理身份资料、密码、登录设备与旧版数据迁移。</p></section><p v-if="message" class="success-text">{{message}}</p><p v-if="error" class="error-text">{{error}}</p><section class="settings-grid account-grid"><form class="editor-card account-panel" @submit.prevent="saveProfile"><div><strong class="panel-number small">01</strong><h2>个人资料</h2><p>显示名称用于客户端顶部与后续协作界面，邮箱作为登录标识，不能在此处直接修改。</p></div><label>显示名称<input v-model="profile.displayName" maxlength="80" required/></label><label>登录邮箱<input :value="auth.user?.email" disabled/></label><button class="btn primary" :disabled="accountBusy">保存资料</button></form><form class="editor-card account-panel" @submit.prevent="changePassword"><div><strong class="panel-number small">02</strong><h2>修改密码</h2><p>修改成功后，所有设备都会退出，需使用新密码重新登录。</p></div><label>当前密码<input v-model="password.currentPassword" type="password" autocomplete="current-password" required/></label><label>新密码<input v-model="password.newPassword" type="password" minlength="10" pattern="(?=.*[A-Za-z])(?=.*\d).+" autocomplete="new-password" required/></label><label>确认新密码<input v-model="password.confirmPassword" type="password" autocomplete="new-password" required/></label><button class="btn danger" :disabled="accountBusy">更新密码并退出</button></form></section><EmailVerificationPanel/><EmailChangePanel/><LegacyRecyclingPanel/><section class="section"><div class="section-title"><div><strong class="panel-number small">03</strong><h2>登录会话</h2></div><button class="btn danger" :disabled="busy||!sessions.length" @click="logoutEverywhere">退出全部设备</button></div><div v-if="!sessions.length" class="empty">没有可用的刷新会话。</div><div v-for="item in sessions" :key="item.id" class="migration-row"><div><strong>{{item.current?'当前设备':'其他设备'}}</strong><p>登录于 {{new Date(item.createdAt).toLocaleString()}} · 到期 {{new Date(item.expiresAt).toLocaleString()}}</p></div><span class="migration-status">{{item.current?'CURRENT':'ACTIVE'}}</span><button class="btn danger" :disabled="busy" @click="revokeSession(item)">退出此设备</button></div></section><section class="section settings-grid"><div><strong class="panel-number">04</strong><h2>选择旧版 JSON</h2><p>请从旧版计划控制台重新导出备份。新版导出会携带暑假计划、吉他和项目升级路线的任务目录。</p><p>较早的备份仍可上传，但预检会明确列出只能保存在原始快照中的数据。</p></div><div class="upload-box"><label class="file-button">选择 JSON<input type="file" accept="application/json,.json" @change="choose"/></label><strong>{{fileName||'尚未选择文件'}}</strong><template v-if="preview"><div class="migration-metrics"><span>计划 <b>{{preview.plans}}</b></span><span>任务 <b>{{preview.tasks}}</b></span><span>目标路线 <b>{{preview.mainlines}}</b></span><span>步骤 <b>{{preview.mainlineItems}}</b></span><span>复盘 <b>{{preview.reflections}}</b></span><span>计时 <b>{{preview.timeEntries}}</b></span></div><ul v-if="preview.warnings.length" class="warning-list"><li v-for="item in preview.warnings" :key="item">{{item}}</li></ul></template><button class="btn primary" :disabled="!preview?.ready||busy" @click="migrate">{{busy?'处理中…':'确认迁移'}}</button></div></section><section class="section"><div class="section-title"><div><strong class="panel-number small">05</strong><h2>迁移历史</h2></div><span>{{history.length}}</span></div><div v-if="!history.length" class="empty">还没有迁移记录。</div><div v-for="item in history" :key="item.importId" class="migration-row"><div><strong>{{item.sourceVersion}}</strong><p>{{item.importId}} · {{new Date(item.createdAt).toLocaleString()}}</p></div><span class="migration-status">{{item.status}}</span><button v-if="item.status==='COMPLETED'" class="btn danger" :disabled="busy" @click="rollback(item)">回滚本批</button></div></section><section class="section"><strong class="panel-number">06</strong><h2>客户端路线</h2><div class="roadmap"><article><strong>Web</strong><p>Vue 3 当前实现，作为所有客户端的业务基准。</p></article><article><strong>Windows</strong><p>Tauri 客户端已提供，复用相同账号与业务 API。macOS 暂未提供安装包。</p></article><article><strong>Android</strong><p>Capacitor 客户端已提供给受邀成员测试，使用同一云端账号同步数据；官网 APK 下载暂未开放。</p></article><article><strong>微信小程序</strong><p>使用独立 UI 层复用账号和业务 API。</p></article></div></section></div></template>
